using System;
using System.Collections.Generic;
using System.Collections.Immutable;
using System.IO;
using System.Linq;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using MitchEngine.Generators;
using Xunit;

// Hosts the real generator on in-memory compilations: snapshot, diagnostics and
// does-the-generated-code-compile checks.
public class GeneratorDriverTests
{
    internal sealed class RunResult
    {
        public ImmutableArray<Diagnostic> GeneratorDiagnostics;
        public ImmutableArray<Diagnostic> CompileDiagnostics;
        // The first generated file (single-generator runs), and every file by hint name.
        public string Generated = "";
        public Dictionary<string, string> Sources = new();
    }


    // Runs the given generators (the schema generator when none are given) over one source file.
    internal static RunResult Run(string source, params IIncrementalGenerator[] generators)
    {
        var references = new List<MetadataReference>();
        var trusted = (string)AppContext.GetData("TRUSTED_PLATFORM_ASSEMBLIES")!;
        foreach (var path in trusted.Split(Path.PathSeparator))
        {
            references.Add(MetadataReference.CreateFromFile(path));
        }
        references.Add(MetadataReference.CreateFromFile(typeof(ScriptCore.Generation.GenerateSchemaAttribute).Assembly.Location));

        var compilation = CSharpCompilation.Create(
            "GeneratorDriverTests.Probe",
            new[] { CSharpSyntaxTree.ParseText(source) },
            references,
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));

        if (generators.Length == 0)
        {
            generators = new IIncrementalGenerator[] { new SchemaGenerator() };
        }
        GeneratorDriver driver = CSharpGeneratorDriver.Create(generators);
        driver = driver.RunGeneratorsAndUpdateCompilation(compilation, out var outputCompilation, out _);

        var result = new RunResult { CompileDiagnostics = outputCompilation.GetDiagnostics() };
        var diagnostics = ImmutableArray.CreateBuilder<Diagnostic>();
        foreach (var runResult in driver.GetRunResult().Results)
        {
            diagnostics.AddRange(runResult.Diagnostics);
            foreach (var generated in runResult.GeneratedSources)
            {
                var text = generated.SourceText.ToString();
                result.Sources[generated.HintName] = text;
                if (result.Generated.Length == 0)
                {
                    result.Generated = text;
                }
            }
        }
        result.GeneratorDiagnostics = diagnostics.ToImmutable();
        return result;
    }


    internal static string Normalize(string text) => text.Replace("\r\n", "\n");


    [Fact]
    public void Snapshot_of_a_minimal_type()
    {
        var result = Run(@"using ScriptCore.Generation;

[GenerateSchema]
public partial class MiniProbe
{
    public float Speed;
}
");
        Assert.Empty(result.GeneratorDiagnostics);
        Assert.Empty(result.CompileDiagnostics.Where(d => d.Severity == DiagnosticSeverity.Error));

        const string expected = @"// <auto-generated by MitchEngine.Generators (CS-9); do not edit.>
#nullable enable
#pragma warning disable

partial class MiniProbe
{
    /// <summary>Generated field schema (CS-9): names, kinds and boxed accessors.</summary>
    public static global::ScriptCore.Generation.TypeSchema Schema { get; } = new global::ScriptCore.Generation.TypeSchema(
        ""MiniProbe"",
        0x5101587331CFF1AFUL,
        new global::ScriptCore.Generation.FieldDescriptor[]
        {
            new global::ScriptCore.Generation.FieldDescriptor( ""Speed"", global::ScriptCore.Generation.FieldKind.Float, ""float"",
                static instance => ((global::MiniProbe)instance).Speed,
                static ( instance, value ) => ((global::MiniProbe)instance).Speed = (float)value! ),
        } );

    /// <summary>Writes the fields as one JSON object, matching ScriptSerializer's shape.</summary>
    public void SaveFields( global::System.Text.Json.Utf8JsonWriter writer )
    {
        writer.WriteStartObject();
        writer.WriteNumber( ""Speed"", this.Speed );
        writer.WriteEndObject();
    }

    /// <summary>Reads fields from a JSON object written by SaveFields or ScriptSerializer.</summary>
    public void LoadFields( global::System.Text.Json.JsonElement element )
    {
        if( element.ValueKind != global::System.Text.Json.JsonValueKind.Object )
        {
            return;
        }
        {
            global::System.Text.Json.JsonElement value;
            float parsed;
            if( element.TryGetProperty( ""Speed"", out value ) && value.ValueKind == global::System.Text.Json.JsonValueKind.Number && value.TryGetSingle( out parsed ) )
            {
                this.Speed = parsed;
            }
        }
    }

    [global::System.Runtime.CompilerServices.ModuleInitializer]
    internal static void __RegisterGeneratedSchema()
    {
        global::ScriptCore.Generation.SchemaRegistry.Register( typeof( global::MiniProbe ), Schema );
    }
}
";
        Assert.Equal(Normalize(expected), Normalize(result.Generated));
    }


    [Fact]
    public void Namespaced_types_generate_and_compile()
    {
        var result = Run(@"using ScriptCore.Generation;

namespace Game.Scripts
{
    [GenerateSchema]
    public partial class Walker
    {
        public int Steps;
        public Vector3 Target;
    }
}
");
        Assert.Empty(result.GeneratorDiagnostics);
        Assert.Empty(result.CompileDiagnostics.Where(d => d.Severity == DiagnosticSeverity.Error));
        Assert.Contains("namespace Game.Scripts", result.Generated);
        Assert.Contains("\"Game.Scripts.Walker\"", result.Generated);
        Assert.Contains("SchemaRegistry.Register( typeof( global::Game.Scripts.Walker ), Schema )", result.Generated);
    }


    [Fact]
    public void Schema_hash_is_stable_and_field_sensitive()
    {
        const string source = @"using ScriptCore.Generation;
[GenerateSchema] public partial class Hashed { public int A; }
";
        var first = Run(source);
        var second = Run(source);
        Assert.Equal(first.Generated, second.Generated);

        var changed = Run(@"using ScriptCore.Generation;
[GenerateSchema] public partial class Hashed { public int B; }
");
        string HashOf(string text) => text.Split('\n').Single(l => l.Contains("UL,")).Trim();
        Assert.NotEqual(HashOf(first.Generated), HashOf(changed.Generated));
    }


    [Fact]
    public void NotPartial_reports_MEGEN001_and_generates_nothing()
    {
        var result = Run(@"using ScriptCore.Generation;
[GenerateSchema] public class NotPartial { public int A; }
");
        var diagnostic = Assert.Single(result.GeneratorDiagnostics);
        Assert.Equal("MEGEN001", diagnostic.Id);
        Assert.Equal(DiagnosticSeverity.Error, diagnostic.Severity);
        Assert.Equal("", result.Generated);
    }


    [Fact]
    public void Nested_and_generic_types_report_MEGEN003()
    {
        var nested = Run(@"using ScriptCore.Generation;
public partial class Outer { [GenerateSchema] public partial class Inner { public int A; } }
");
        Assert.Contains(nested.GeneratorDiagnostics, d => d.Id == "MEGEN003");

        var generic = Run(@"using ScriptCore.Generation;
[GenerateSchema] public partial class Generic<T> { public int A; }
");
        Assert.Contains(generic.GeneratorDiagnostics, d => d.Id == "MEGEN003");
    }


    [Fact]
    public void Unsupported_and_hidden_fields_are_excluded()
    {
        var result = Run(@"using System.Collections.Generic;
using ScriptCore;
using ScriptCore.Generation;

[GenerateSchema]
public partial class Mixed
{
    public float Kept;
    public List<int> Skipped;
    public readonly int Frozen = 1;
    [HideInInspector] public int Hushed;
}
");
        // One warning each for the unsupported list and the readonly field; the hidden one is silent.
        Assert.Equal(2, result.GeneratorDiagnostics.Length);
        Assert.All(result.GeneratorDiagnostics, d => Assert.Equal("MEGEN002", d.Id));
        Assert.All(result.GeneratorDiagnostics, d => Assert.Equal(DiagnosticSeverity.Warning, d.Severity));
        Assert.Contains("\"Kept\"", result.Generated);
        Assert.DoesNotContain("\"Skipped\"", result.Generated);
        Assert.DoesNotContain("\"Frozen\"", result.Generated);
        Assert.DoesNotContain("\"Hushed\"", result.Generated);
        Assert.Empty(result.CompileDiagnostics.Where(d => d.Severity == DiagnosticSeverity.Error));
    }
}
